import { withDemoTrafficLimit, type DemoTrafficEnv } from "./demo-traffic-limit";
import { createRequestHandler, type ServerBuild } from "react-router";
// @ts-expect-error generated by the explicit public-demo build
import * as generatedBuild from "../build/server/index.js";

const handleRequest = createRequestHandler(generatedBuild as ServerBuild, "production");
type DemoEnv = DemoTrafficEnv & { ASSETS: { fetch(request: Request): Promise<Response> } };
// Separate fictional-data sample entry; production serves the live public catalogue.
export default {
  fetch(request: Request, env: DemoEnv) {
    if (new URL(request.url).pathname.startsWith("/assets/")) return env.ASSETS.fetch(request);
    return withDemoTrafficLimit(request, env, () => handleRequest(request, { cloudflare: { env: {} } }));
  },
};
